import * as actions from '../actions/backorder-list.action';
import { BackorderListStateRecord } from './backorder-list.state';
export const initialState = new BackorderListStateRecord();
export function reducer(state = initialState, {
  type,
  payload
}) {
  if (!type) {
    return state;
  }

  switch (type) {
    // <------------------BACKORDER LIST--------------------> //
    case actions.ActionTypes.BACKORDER_LIST_ACTION:
      {
        return Object.assign({}, state, {
          backorderList: [],
          backorderListLoading: false,
          backorderListLoaded: false,
          backorderListFailed: false
        });
      }

    case actions.ActionTypes.BACKORDER_LIST_SUCCESS:
      {
        let tempBackorderList = [];

        if (payload.data && payload.data.length > 0) {
          tempBackorderList = payload.data.map(element => {
            return Object.assign(Object.assign({}, element), {
              isCollapsed: true
            });
          });
        }

        return Object.assign({}, state, {
          backorderList: tempBackorderList,
          backorderListLoading: false,
          backorderListLoaded: false,
          backorderListFailed: false
        });
      }

    case actions.ActionTypes.BACKORDER_LIST_FAIL:
      {
        return Object.assign({}, state, {
          backorderList: [],
          backorderListLoading: false,
          backorderListLoaded: false,
          backorderListFailed: false
        });
      }
    // <------------------BACKORDER LIST COUNT--------------------> //

    case actions.ActionTypes.BACKORDER_LIST_COUNT_ACTION:
      {
        return Object.assign({}, state, {
          backorderListCount: '',
          backorderListCountLoading: false,
          backorderListCountLoaded: false,
          backorderListCountFailed: false
        });
      }

    case actions.ActionTypes.BACKORDER_LIST_COUNT_SUCCESS:
      {
        return Object.assign({}, state, {
          backorderListCount: payload.data,
          backorderListCountLoading: false,
          backorderListCountLoaded: false,
          backorderListCountFailed: false
        });
      }

    case actions.ActionTypes.BACKORDER_LIST_COUNT_FAIL:
      {
        return Object.assign({}, state, {
          backorderListCount: '',
          backorderListCountLoading: false,
          backorderListCountLoaded: false,
          backorderListCountFailed: false
        });
      }

    default:
      {
        return state;
      }
  }
} //

export const backorderList = state => state.backorderList;
export const backorderListLoading = state => state.backorderListLoading;
export const backorderListLoaded = state => state.backorderListLoaded;
export const backorderListCount = state => state.backorderListCount;
export const backorderListCountLoading = state => state.backorderListCountLoading;
export const backorderListCountLoaded = state => state.backorderListCountLoaded;
